	If ($Talkzx023 == 1) @Talk1;
	Goto @end;
@Talk0:
	If ($ZiXuanSense >> 20) @AddSenseEnd1;
	Add($ZiXuanSense, 5);
	Add($SenseVal, 5);
@AddSenseEnd1:
	Talk(2381, 2383);
	Assign($Talkzx023, 1);
	Return;
@Talk1:	
	If ($ZiXuanSense >> 20) @AddSenseEnd2;
